/**
 * Harel First Class annual proposal templates (51878.15 annual, 51878.21 annual extended, 12/2024)
 * and the Heebo font, embedded so the edge function always has them.
 */
export const ANNUAL_BASIC_PDF_BASE64 = "";

export const ANNUAL_EXTENDED_PDF_BASE64 = "";

export const HEEBO_FONT_BASE64 = "";

export function decodeBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
